import base64,csv,gc,hashlib,io,json,math,subprocess,sys,tarfile
from pathlib import Path
subprocess.run([sys.executable,'-m','pip','uninstall','-y','torchao'],check=True)
import torch
if not torch.cuda.is_available(): raise RuntimeError('CUDA required')
raw=base64.b64decode('')
if hashlib.sha256(raw).hexdigest()!='c81a46b0309f9a5a967969b5e221af1cd83ceb1193223ef423798bcbdc8c6ff0': raise RuntimeError('source hash mismatch')
root=Path('/kaggle/temp/filtered-eval-src');root.mkdir(parents=True,exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(raw),mode='r:gz') as outer:
    for member in outer.getmembers():
        with tarfile.open(fileobj=io.BytesIO(outer.extractfile(member).read()),mode='r:') as inner:
            inner.extractall(root,filter='data')
sys.path[:0]=[str(root/'packages/ekido_core'),str(root/'runtime')]
from ekido_core.canonical import document_hash
from ekido_core.gpck import load_checkpoint
from ekido_core.recipes import recipe,passes,score,eval_set_hash
from ekido_runtime.llm import load_model,load_tokenizer,generate_answers
from ekido_runtime.train import apply_lora,_trainable
CHALLENGE=''
CHALLENGE_SHA='17c7eefa1542fa6a2902a5310ff5e6f5ab205bb937f5ab93194bf61f652c89c4'

raw_test=base64.b64decode(CHALLENGE)
if hashlib.sha256(raw_test).hexdigest()!=CHALLENGE_SHA:raise RuntimeError('challenge bytes mismatch')
test=list(csv.DictReader(io.StringIO(raw_test.decode('utf-8'),newline='')))
if len(test)!=60:raise RuntimeError('expected 60 challenge rows')
sources=[]
for p in Path('/kaggle/input').rglob('distill_evidence.json'):
    if json.loads(p.read_text(encoding='utf-8')).get('recipe_id')=='invoice-fields':sources.append(p.parent)
if len(sources)!=1:raise RuntimeError('expected one invoice checkpoint source')
source=sources[0]
spec=json.loads((source/'student_spec.json').read_text(encoding='utf-8'))
recorded=json.loads((source/'student/evidence.json').read_text(encoding='utf-8'))
blob=(source/'student_dataset.jsonl').read_bytes()
if hashlib.sha256(blob).hexdigest()!=spec['dataset']['sha256']:raise RuntimeError('student dataset hash mismatch')
name='invoice-fields';r=recipe(name);a,b=r.columns
tok=load_tokenizer(spec['model']['id'],spec['model']['revision'])
instruction='Return date as YYYY-MM-DD and total as a decimal string with two digits after the point and no commas.'
prompts=[f'{r.instruction} {instruction}\n{r.input_name}: {row[a].strip()}\n{r.answer_name}:' for row in test]
limit=spec['max_seq_length']-r.max_answer_tokens
if any(len(tok(p,add_special_tokens=False)['input_ids'])>limit for p in prompts):raise RuntimeError('prompt truncation')
model=load_model(spec['model']['id'],spec['model']['revision'],device='cuda')
out=Path('/kaggle/working/invoice-challenge-eval');out.mkdir(parents=True,exist_ok=True)
result={'challenge_sha256':CHALLENGE_SHA,'eval_set_hash':eval_set_hash(name,test),'rows':len(test),
        'output_instruction':instruction,'model':spec['model'],'historical_student_rate':recorded['eval']['pass_rate'],
        'note':'Exploratory evaluation of a newly generated synthetic challenge. Not a customer-data result or a quality gate.'}
def evaluate(arm):
    answers=generate_answers(model,tok,prompts,max_new_tokens=r.max_answer_tokens,max_prompt_tokens=limit,device='cuda')
    if len(answers)!=len(test):raise RuntimeError('incomplete answers')
    details=[{'input':row[a],'reference':row[b],'answer':answer,'passed':bool(passes(name,answer,row[b]))}
             for row,answer in zip(test,answers)]
    result[arm]={'pass_rate':sum(x['passed'] for x in details)/len(details),
                 'mean_score':score(name,answers,[row[b] for row in test]),'predictions':details}
    (out/'summary.json').write_text(json.dumps(result,indent=2,ensure_ascii=False),encoding='utf-8')
    print('CHALLENGE',arm,result[arm]['pass_rate'],result[arm]['mean_score'],flush=True)
evaluate('base')
model=apply_lora(model,spec)
named=_trainable(model);shapes={key:tuple(value.shape) for key,value in named.items()}
manifest,weights,_=load_checkpoint(source/'student/checkpoints/step-50',shapes,dtype=torch.float32,expected_immutable_hash=document_hash(spec))
if manifest['logical_step']!=50:raise RuntimeError('unexpected checkpoint')
with torch.no_grad():
    for key,param in named.items():param.copy_(weights[key].to(param.device,param.dtype))
result['checkpoint_manifest']=manifest
evaluate('student')
